 public static void Boss(){if(!Application.isBatchMode)throw new Exception("Exclusive owned batch required");var scene=EditorSceneManager.OpenScene("Assets/Scenes/BossFight.unity",OpenSceneMode.Single);BossOpaqueFramingRefinement.ApplyAfterGrant();var manager=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<BossArenaManager>(true)).Single();var m=new SerializedObject(manager);var board=(BossDefenseBoard)m.FindProperty("_Defenses").objectReferenceValue;string path="Assets/Resources/BossFight/SceneObjects/TunaLabel.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(!material){material=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="Tuna can - original label and metal lid"};AssetDatabase.CreateAsset(material,path);}var texture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Art/CanOfTuna/TunaCanTexture.png");if(!texture)throw new Exception("Verified source tuna label missing");material.SetTexture("_BaseMap",texture);material.SetColor("_BaseColor",Color.white);material.SetFloat("_Metallic",.12f);material.SetFloat("_Smoothness",.35f);EditorUtility.SetDirty(material);
 foreach(int slot in new[]{1,4}){var p=new SerializedObject(board.Piece(slot));foreach(string field in new[]{"_Healthy","_Broken"})foreach(var renderer in ((GameObject)p.FindProperty(field).objectReferenceValue).GetComponentsInChildren<MeshRenderer>(true))renderer.sharedMaterials=Enumerable.Repeat(material,renderer.sharedMaterials.Length).ToArray();}
 EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();BossCompositionIntegrationBatch.ValidateOnly();}
